<?php $this->layout('default', ['title' => 'Criar conta | Realizze', 'description' => 'Escolha o perfil e conheça o cadastro do Realizze.']); $this->start('optout'); $this->stop(); ?>
<style>
.register-shell{max-width:680px;margin:42px auto;padding:0 20px 56px}.register-card{background:#fff;border-radius:20px;padding:36px;box-shadow:0 12px 48px #153d2612}.register-card h1{font-size:30px;line-height:1.2;margin:8px 0}.register-card p{color:#66756d}.register-progress{display:flex;gap:8px;margin:24px 0}.register-progress span{height:5px;flex:1;border-radius:8px;background:#e6ece8}.register-progress span.active{background:#079653}.register-options{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:24px 0}.register-choice{border:1px solid #e1e9e4;border-radius:14px;padding:20px;text-align:left;background:#fff;cursor:pointer;color:#223b2c}.register-choice strong{display:block;margin-bottom:7px;font-size:16px}.register-choice small{display:block;color:#6c7b72}.register-choice.selected{border:2px solid #079653;background:#f1faf5}.register-field{display:flex;flex-direction:column;gap:6px;margin:15px 0}.register-field label{font-weight:600;font-size:13px}.register-field input,.register-field select{width:100%;padding:12px 14px;border:1px solid #dce6df;border-radius:10px;background:white;color:#1c3225}.register-actions{display:flex;justify-content:space-between;gap:12px;margin-top:24px}.register-actions button{border-radius:10px;padding:12px 22px;border:1px solid #dce6df;cursor:pointer;background:#fff}.register-actions button.primary{background:#079653;color:white;border-color:#079653;margin-left:auto}.register-actions button:disabled{opacity:.5;cursor:not-allowed}.register-step[hidden]{display:none}.register-info{background:#f0f8f3;border-radius:12px;padding:14px;margin-top:16px;font-size:13px;color:#335f43}.register-bottom{text-align:center;margin-top:20px}.register-summary{background:#f7faf8;padding:16px;border-radius:12px;line-height:1.8;overflow-wrap:anywhere}@media(max-width:540px){.register-card{padding:22px}.register-options{grid-template-columns:1fr}.register-card h1{font-size:25px}}
</style>
<section class="register-shell"><div class="register-card" id="realizze-register">
<span class="eyebrow">COMECE POR AQUI</span><h1>Seu financeiro, do seu jeito.</h1><p>Escolha como deseja usar o Realizze.</p>
<div class="register-progress" aria-label="Progresso do cadastro"><span class="active"></span><span></span><span></span><span></span></div>
<form id="register-wizard" novalidate>
<section class="register-step" data-step="0"><h2>Como você vai usar?</h2><div class="register-options"><button type="button" class="register-choice selected" data-profile="pf" aria-pressed="true"><strong>Para mim</strong><small>Organize suas finanças pessoais.</small></button><button type="button" class="register-choice" data-profile="pj" aria-pressed="false"><strong>Para minha empresa</strong><small>Controle o financeiro do seu negócio.</small></button></div></section>
<section class="register-step" data-step="1" hidden><h2>Seus dados</h2><div class="register-field"><label for="register-name">Nome completo</label><input id="register-name" name="name" autocomplete="name" maxlength="160" required></div><div class="register-field"><label for="register-email">E-mail</label><input id="register-email" name="email" type="email" autocomplete="email" maxlength="254" required></div></section>
<section class="register-step" data-step="2" hidden><div id="register-pj-fields" hidden><h2>Sobre a empresa</h2><div class="register-field"><label for="register-company">Nome da empresa</label><input id="register-company" name="company" maxlength="180"></div><div class="register-field"><label for="register-cnpj">CNPJ</label><input id="register-cnpj" name="cnpj" inputmode="numeric" maxlength="18" placeholder="00.000.000/0000-00"></div><div class="register-field"><label for="register-tax">Regime tributário</label><select id="register-tax" name="tax"><option value="">Selecionar depois</option><option value="mei">MEI / SIMEI</option><option value="simples">Simples Nacional</option><option value="presumido">Lucro Presumido</option><option value="real">Lucro Real</option><option value="nao-sei">Não sei informar</option></select></div></div><div id="register-pf-fields"><h2>Suas preferências</h2><p>Seu espaço pessoal terá contas, cartões, planejamento e metas. Você poderá adicionar uma empresa futuramente.</p></div></section>
<section class="register-step" data-step="3" hidden><h2>Segurança e revisão</h2><div class="register-field"><label for="register-password">Crie uma senha</label><input id="register-password" name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></div><div class="register-field"><label for="register-confirm">Confirme a senha</label><input id="register-confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></div><div class="register-summary" id="register-summary" aria-live="polite"></div><div class="register-info">Prévia do fluxo: o envio ainda não está conectado ao cadastro seguro do servidor. Nenhuma conta será criada nesta tela.</div></section>
<div class="register-actions"><button type="button" id="register-back" hidden>Voltar</button><button type="button" class="primary" id="register-next">Continuar</button></div><p role="status" aria-live="polite" id="register-feedback"></p>
</form><p class="register-bottom">Já tem cadastro? <a href="/entrar">Entrar</a></p></div></section>
<script>
(()=>{'use strict';const root=document.getElementById('realizze-register');if(!root)return;let step=0,profile='pf';const steps=[...root.querySelectorAll('.register-step')],bars=[...root.querySelectorAll('.register-progress span')],back=root.querySelector('#register-back'),next=root.querySelector('#register-next'),feedback=root.querySelector('#register-feedback');function update(){steps.forEach((el,i)=>el.hidden=i!==step);bars.forEach((el,i)=>el.classList.toggle('active',i<=step));back.hidden=step===0;next.textContent=step===3?'Concluir prévia':'Continuar';root.querySelector('#register-pj-fields').hidden=profile!=='pj';root.querySelector('#register-pf-fields').hidden=profile==='pj';if(step===3){const name=root.querySelector('#register-name').value.trim();const email=root.querySelector('#register-email').value.trim();const company=root.querySelector('#register-company').value.trim();const summary=root.querySelector('#register-summary');summary.replaceChildren();for(const [label,value] of [['Perfil',profile==='pj'?'Empresarial':'Pessoal'],['Nome',name],['E-mail',email],...(profile==='pj'?[['Empresa',company]]:[])]){const line=document.createElement('div');const strong=document.createElement('strong');strong.textContent=label+': ';line.append(strong,document.createTextNode(value));summary.append(line)}}feedback.textContent=''}root.querySelectorAll('[data-profile]').forEach(button=>button.addEventListener('click',()=>{profile=button.dataset.profile;root.querySelectorAll('[data-profile]').forEach(el=>{const selected=el===button;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected))})}));back.addEventListener('click',()=>{step=Math.max(0,step-1);update()});next.addEventListener('click',()=>{if(step===1){const fields=[root.querySelector('#register-name'),root.querySelector('#register-email')];for(const field of fields){if(!field.checkValidity()){field.reportValidity();return}}}if(step===2&&profile==='pj'){const company=root.querySelector('#register-company'),cnpj=root.querySelector('#register-cnpj');if(!company.value.trim()){company.setCustomValidity('Informe o nome da empresa');company.reportValidity();company.setCustomValidity('');return}if(cnpj.value.replace(/\D/g,'').length!==14){cnpj.setCustomValidity('Informe os 14 dígitos do CNPJ');cnpj.reportValidity();cnpj.setCustomValidity('');return}}if(step===3){const password=root.querySelector('#register-password'),confirm=root.querySelector('#register-confirm');if(!password.checkValidity()){password.reportValidity();return}if(password.value!==confirm.value){feedback.textContent='As senhas não conferem.';return}feedback.textContent='Prévia concluída. O cadastro real será ativado após a integração segura com o servidor.';return}step=Math.min(3,step+1);update()});root.querySelector('#register-wizard').addEventListener('submit',event=>event.preventDefault());update()})();
</script>
